import java.util.Scanner;

public class Words {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        char[] ch = sc.next().toCharArray();
        int[] temp = new int[n];
        int count = 0;
        int k = 0;
        boolean inside = ch[0] == '(';
        int i = 0;

        while (i < n) {
            char c = ch[i];
            if (!inside) {
                if (c == '_') {
                    k++;
                } else {
                    if (c == '(') {
                        inside = true;
                    } else {
                        temp[k]++;
                    }
                }
            } else {
                if (c == ')') {
                    inside = false;
                    k++;
                } else if (i > 0 && (ch[i - 1] == '(' || ch[i - 1] == '_') && c != '_' && c != '(') {
                    count++;
                }
            }
            i++;
        }

        int swap;
        for (int a = 0; a < n; a++) {
            for (int b = a; b > 0; b--) {
                if (temp[b] > temp[b - 1]) {
                    swap = temp[b];
                    temp[b] = temp[b - 1];
                    temp[b - 1] = swap;
                }
            }
        }

        System.out.println(temp[0]);
        System.out.println(count);
    }
}
